exercises.reference:
import numpy as np

def lookup(parent, edges, target, source):
    def to_root(frame):
        T = np.eye(3)
        while frame in parent:
            T = edges[frame] @ T
            frame = parent[frame]
        return T, frame
    root_T_source, r1 = to_root(source)
    root_T_target, r2 = to_root(target)
    if r1 != r2:
        raise LookupError("frames are not in one tree")
    return np.linalg.inv(root_T_target) @ root_T_source
